// CodeMirror 6 highlighting for BigFix Relevance (#142, Layer 4).
//
// Generated by tools/generate_tmlanguage.py from the rules of the TextMate
// grammar it also writes (bigfix-relevance.tmLanguage.json), so the editor in
// VS Code and in a browser color the same text the same way; do not edit by
// hand. tools/editor-client's Node tests hold the two to each other, character
// for character, over tests/corpus.
//
// Shipped in the wheel next to relevance_editor.js. It imports nothing: pass
// the page's CodeMirror namespace, which needs only StreamLanguage
// (@codemirror/language >= 6.11):
//
//   extensions: [relevanceLanguage(CM), relevanceEditor(CM, transport)]
//
// Lexical, like the TextMate grammar: keywords, operators, literals and
// comments. Inspector names stay uncolored; telling them apart takes the parser.

/** The CodeMirror names this module uses. */
export const REQUIRED_CM = ["StreamLanguage"];

/** The token (a @lezer/highlight tag name) each TextMate scope becomes. */
export const TEXTMATE_TOKENS = {
  "comment.block.bigfix-relevance": "blockComment",
  "constant.character.escape.bigfix-relevance": "escape",
  "constant.language.bigfix-relevance": "bool",
  "constant.numeric.integer.bigfix-relevance": "number",
  "keyword.control.conditional.bigfix-relevance": "controlKeyword",
  "keyword.control.filter.bigfix-relevance": "controlKeyword",
  "keyword.operator.arithmetic.bigfix-relevance": "operatorKeyword",
  "keyword.operator.bigfix-relevance": "operator",
  "keyword.operator.cast.bigfix-relevance": "operatorKeyword",
  "keyword.operator.comparison.bigfix-relevance": "operatorKeyword",
  "keyword.operator.logical.bigfix-relevance": "operatorKeyword",
  "keyword.operator.of.bigfix-relevance": "operatorKeyword",
  "punctuation.section.parens.bigfix-relevance": "paren",
  "punctuation.separator.bigfix-relevance": "separator",
  "string.quoted.double.bigfix-relevance": "string",
  "variable.language.it.bigfix-relevance": "variableName.special",
};

// Each rule in the TextMate grammar's order: at a position, the first that
// matches there wins, as in TextMate. Sticky, so a word boundary still sees the
// character before the position.
const RULES = [
  ["number", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))[0-9]+(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "uy")],
  ["operatorKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:mod)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["operatorKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:is\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*greater\\s+(?:(?:a|an|the)\\s+)*than\\s+(?:(?:a|an|the)\\s+)*or\\s+(?:(?:a|an|the)\\s+)*equal\\s+(?:(?:a|an|the)\\s+)*to|is\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*less\\s+(?:(?:a|an|the)\\s+)*than\\s+(?:(?:a|an|the)\\s+)*or\\s+(?:(?:a|an|the)\\s+)*equal\\s+(?:(?:a|an|the)\\s+)*to|is\\s+(?:(?:a|an|the)\\s+)*greater\\s+(?:(?:a|an|the)\\s+)*than\\s+(?:(?:a|an|the)\\s+)*or\\s+(?:(?:a|an|the)\\s+)*equal\\s+(?:(?:a|an|the)\\s+)*to|is\\s+(?:(?:a|an|the)\\s+)*less\\s+(?:(?:a|an|the)\\s+)*than\\s+(?:(?:a|an|the)\\s+)*or\\s+(?:(?:a|an|the)\\s+)*equal\\s+(?:(?:a|an|the)\\s+)*to|does\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*start\\s+(?:(?:a|an|the)\\s+)*with|is\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*contained\\s+(?:(?:a|an|the)\\s+)*by|is\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*greater\\s+(?:(?:a|an|the)\\s+)*than|does\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*end\\s+(?:(?:a|an|the)\\s+)*with|does\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*contain|is\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*less\\s+(?:(?:a|an|the)\\s+)*than|is\\s+(?:(?:a|an|the)\\s+)*contained\\s+(?:(?:a|an|the)\\s+)*by|is\\s+(?:(?:a|an|the)\\s+)*greater\\s+(?:(?:a|an|the)\\s+)*than|is\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*equal\\s+(?:(?:a|an|the)\\s+)*to|does\\s+(?:(?:a|an|the)\\s+)*not\\s+(?:(?:a|an|the)\\s+)*equal|is\\s+(?:(?:a|an|the)\\s+)*less\\s+(?:(?:a|an|the)\\s+)*than|is\\s+(?:(?:a|an|the)\\s+)*equal\\s+(?:(?:a|an|the)\\s+)*to|starts\\s+(?:(?:a|an|the)\\s+)*with|ends\\s+(?:(?:a|an|the)\\s+)*with|contains|equals|is\\s+(?:(?:a|an|the)\\s+)*not|is)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["operatorKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:and|or)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["controlKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:else|then|if)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["controlKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:whose)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["operatorKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:as)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["operatorKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:exists|exist|not)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["operatorKeyword", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:of)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["variableName.special", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:it)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["bool", new RegExp("(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))(?:false|true)(?:(?<=[\\p{L}\\p{M}\\p{N}\\p{Pc}])(?![\\p{L}\\p{M}\\p{N}\\p{Pc}])|(?<![\\p{L}\\p{M}\\p{N}\\p{Pc}])(?=[\\p{L}\\p{M}\\p{N}\\p{Pc}]))", "iuy")],
  ["operator", new RegExp("!=|<=|>=|\\&|\\*|\\+|\\-|/|<|=|>|\\|", "y")],
  ["separator", new RegExp("[;,]", "y")],
  ["paren", new RegExp("[()]", "y")],
];

const COMMENT_BEGIN = new RegExp("/\\*", "y");
const COMMENT_END = new RegExp("\\*/", "g");
const STRING_BEGIN = new RegExp("\"", "y");
const STRING_END = new RegExp("\"", "g");
const ESCAPE = new RegExp("%[0-9A-Fa-f]{2}", "g");
const WORD = new RegExp("[\\p{L}\\p{M}\\p{N}\\p{Pc}]+", "uy");

/** The first match of global `regex` in `text` at or after `from`, or null. */
function search(regex, text, from) {
  regex.lastIndex = from;
  return regex.exec(text);
}

/** Whether sticky `regex` matches `text` at `at`; its length, or -1. */
function at(regex, text, from) {
  regex.lastIndex = from;
  const match = regex.exec(text);
  return match ? match[0].length : -1;
}

function token(stream, state) {
  const text = stream.string;
  if (state.inside === "comment") {
    const end = search(COMMENT_END, text, stream.pos);
    if (end) {
      stream.pos = end.index + end[0].length;
      state.inside = null;
    } else stream.skipToEnd();
    return "blockComment";
  }
  if (state.inside === "string") {
    // The end and the escapes compete as in TextMate: the earliest wins, the
    // end on a tie (it is tried first).
    const end = search(STRING_END, text, stream.pos);
    const escape = search(ESCAPE, text, stream.pos);
    const next = [end, escape].filter(Boolean).sort((a, b) => a.index - b.index)[0];
    if (next && next.index === stream.pos) {
      stream.pos += next[0].length;
      if (next === end) {
        state.inside = null;
        return "string";
      }
      return "escape";
    }
    if (next) stream.pos = next.index;
    else stream.skipToEnd();
    return "string";
  }
  if (stream.eatSpace()) return null;
  let length = at(COMMENT_BEGIN, text, stream.pos);
  if (length >= 0) {
    stream.pos += length;
    state.inside = "comment";
    return "blockComment";
  }
  length = at(STRING_BEGIN, text, stream.pos);
  if (length >= 0) {
    stream.pos += length;
    state.inside = "string";
    return "string";
  }
  for (const [name, regex] of RULES) {
    length = at(regex, text, stream.pos);
    if (length > 0) {
      stream.pos += length;
      return name;
    }
  }
  // Nothing starts here. No rule can start inside a run of word characters
  // (each word rule begins at a word boundary), so skip the whole run.
  length = at(WORD, text, stream.pos);
  stream.pos += length > 0 ? length : 1;
  return null;
}

/** The relevance language: a StreamLanguage, an extension in its own right. */
export function relevanceLanguage(CM) {
  const missing = REQUIRED_CM.filter((name) => !(name in CM));
  if (missing.length) throw new Error(`relevanceLanguage: CM lacks ${missing.join(", ")}`);
  return CM.StreamLanguage.define({
    name: "bigfix-relevance",
    startState: () => ({ inside: null }),
    copyState: (state) => ({ inside: state.inside }),
    token,
    languageData: { commentTokens: { block: { open: "/*", close: "*/" } } },
  });
}
